constexpr const char* kTag="MobileI2VGpu";constexpr size_t kW=1280,kH=720,kT=17,kSingle=128*3*23*40,kGuide=128*23*40,kCfg=2*kSingle,kImage=3*kH*kW,kPrompt=2*300*896,kCond=3*23*40,kGuidePlane=23*40,kTextMask=300,kDecoded=3*kT*kH*kW,kPixels=kH*kW;
