std::string str(JNIEnv* e,jstring v){if(!v)return{};const char* c=e->GetStringUTFChars(v,nullptr);if(!c)return{};std::string s(c);e->ReleaseStringUTFChars(v,c);return s;}jstring js(JNIEnv*e,const std::string&s){return e->NewStringUTF(s.c_str());}
float h2f(uint16_t v){uint32_t sign=static_cast<uint32_t>(v&0x8000u)<<16u,ex=(v>>10u)&0x1fu,m=v&0x3ffu,b;if(ex==0){if(m==0)b=sign;else{int sh=0;while((m&0x400u)==0){m<<=1u;++sh;}m&=0x3ffu;b=sign|(static_cast<uint32_t>(127-15-sh+1)<<23u)|(m<<13u);}}else if(ex==0x1fu)b=sign|0x7f800000u|(m<<13u);else b=sign|((ex+112u)<<23u)|(m<<13u);float o;std::memcpy(&o,&b,4);return o;}
bool readPrompt(const std::string&p,std::vector<float>&o){std::ifstream s(p,std::ios::binary|std::ios::ate);if(!s||s.tellg()!=static_cast<std::streamsize>(kPrompt*2))return false;s.seekg(0);std::vector<uint16_t> h(kPrompt);if(!s.read(reinterpret_cast<char*>(h.data()),static_cast<std::streamsize>(h.size()*2)))return false;o.resize(kPrompt);for(size_t i=0;i<kPrompt;i++){o[i]=h2f(h[i]);if(!std::isfinite(o[i]))return false;}return true;}
bool readMask(const std::string&p,std::vector<uint8_t>&o){std::ifstream s(p,std::ios::binary|std::ios::ate);if(!s||s.tellg()!=static_cast<std::streamsize>(kTextMask))return false;s.seekg(0);o.resize(kTextMask);return static_cast<bool>(s.read(reinterpret_cast<char*>(o.data()),kTextMask));}
bool exp(MNN::Interpreter*i,MNN::Session*s,const char*n,size_t c,bool out=false){auto*t=out?i->getSessionOutput(s,n):i->getSessionInput(s,n);return t&&static_cast<size_t>(t->elementSize())==c;}
