std::unique_ptr<RuntimeHandle> create(const std::string&d){auto h=std::make_unique<RuntimeHandle>();if(!readPrompt(d+"/empty_prompt.f16",h->prompt)||!readMask(d+"/empty_prompt_mask.bin",h->mask))return nullptr;h->cond.assign(kCond,0.f);std::fill(h->cond.begin(),h->cond.begin()+kGuidePlane,1.f);h->encoder=mobilei2v::createOpenClSession(d+"/vae_encoder.mnn",d,"vae-encoder-opencl.cache");h->denoiser=mobilei2v::createOpenClSession(d+"/denoiser.mnn",d,"denoiser-opencl.cache");h->decoder=mobilei2v::createOpenClSession(d+"/vae_decoder.mnn",d,"vae-decoder-opencl.cache");return valid(*h)?std::move(h):nullptr;}RuntimeHandle* get(jlong id){auto i=gHandles.find(id);return i==gHandles.end()?nullptr:i->second.get();}
